package com.sistemahospitalar.hospital.controller; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,Object>> notFound(NoSuchElementException e){return body(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class}) ResponseEntity<Map<String,Object>> business(RuntimeException e){return body(HttpStatus.UNPROCESSABLE_ENTITY,e.getMessage());} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> validation(MethodArgumentNotValidException e){Map<String,Object> m=new LinkedHashMap<>();m.put("erro","Dados inválidos");m.put("campos",e.getBindingResult().getFieldErrors().stream().collect(java.util.stream.Collectors.toMap(x->x.getField(),x->x.getDefaultMessage(),(a,b)->a,LinkedHashMap::new)));return ResponseEntity.badRequest().body(m);} private ResponseEntity<Map<String,Object>> body(HttpStatus s,String msg){return ResponseEntity.status(s).body(Map.of("erro",msg));} }
